#include <iostream>
#include<bits/stdc++.h>
using namespace std;
string s;
int T,n;
unordered_set<char>st={'o','x','s','z'};  //单个字符
unordered_set<string>mp={"dp","bq","nu"};  //一对字符
void solve(){
    cin>>s;
    n=s.size();
    int i=0,j=n-1;
    while(i<=j){
        if(s[i]==s[j]){
            if(!st.count(s[i])){  //相等的话 必须要求本身是中心对称的
                puts("no");
                return;
            }
        }
        else{
            string t;
            t.push_back(s[i]);t.push_back(s[j]);
            sort(t.begin(),t.end());
            if(!mp.count(t)){
                puts("no");
                return;
            }
        }
        i++;j--;
    }
    puts("yes");
}
int main() {
    cin>>T;
    while(T--){
        solve();
    }
    return 0;
}
```

