import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int T = Integer.parseInt(br.readLine());
        // 建立镜像映射表
        HashMap<Character, Character> mirror = new HashMap<>();
        mirror.put('n', 'u'); mirror.put('u', 'n');
        mirror.put('w', 'm'); mirror.put('m', 'w');
        mirror.put('p', 'd'); mirror.put('d', 'p');
        mirror.put('q', 'b'); mirror.put('b', 'q');
        mirror.put('x', 'x'); mirror.put('o', 'o');

        StringBuilder sb = new StringBuilder();
        while (T-- > 0) {
            String s = br.readLine();
            int i = 0, j = s.length() - 1;
            boolean ok = true;
            while (i <= j) {
                char left = s.charAt(i), right = s.charAt(j);
                if (left == right) {
                    if (left != 'x' && left != 'o') {
                        ok = false;
                        break;
                    }
                } else {
                    // 检查 left 是否有镜像且镜像等于 right
                    Character mir = mirror.get(left);
                    if (mir == null || mir != right) {
                        ok = false;
                        break;
                    }
                }
                i++;
                j--;
            }
            sb.append(ok ? "yes\n" : "no\n");
        }
        System.out.print(sb);
    }
}
