int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    // 镜像映射表
    unordered_map<char, char> mirror = {
        {'n', 'u'}, {'u', 'n'},
        {'w', 'm'}, {'m', 'w'},
        {'p', 'd'}, {'d', 'p'},
        {'q', 'b'}, {'b', 'q'},
        {'x', 'x'}, {'o', 'o'}
    };

    int T;
    cin >> T;
    while (T--) {
        string s;
        cin >> s;
        int i = 0, j = s.size() - 1;
        bool ok = true;
        while (i <= j) {
            if (s[i] == s[j]) {
                // 自身镜像只能是 'x' 或 'o'
                if (s[i] != 'x' && s[i] != 'o') {
                    ok = false;
                    break;
